#!/usr/bin/env bash
export PATH="/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin:$HOME/.local/bin:$PATH"  # launchd has a minimal PATH; tmux/python3/node live in homebrew, claude itself lives in ~/.local/bin (npm global install, not homebrew)
# affiliate-cli.sh — ALWAYS-ON affiliate earn-core (clone of clip-cli.sh). Detached tmux headless
# claude that registers a DAILY cron: producer writes a deck + builds the slideshow, then run.sh
# posts the carousel to the ready niche account. Idles between; healthcheck restarts if it dies.
set -uo pipefail
SOCK="/tmp/anicca-affiliate-tmux.sock"; SESSION="anicca-affiliate-core"
CLAUDE="$(command -v claude || echo "$HOME/.local/bin/claude")"
STARTUP='You are the Anicca affiliate earn-core (claude-p, every-day loop, AI仕事術 niche, Amazon Associates JP tag aniccaai-22). FIRST register the recurring driver if absent: CronList; if none mentions earn/affiliate, CronCreate cron=<read the single-line file ~/profitable-claude/state/effective-cron/affiliate.txt (this repo, static text) and use its exact content as this cron= value; that file is written by lib/registry-enforce.sh before this session was even spawned> (baseline daily ~08:41 unless a CEO cadence decision has adjusted it), recurring=true, durable=true, prompt="Run ONE daily affiliate pass, no human. set -a; . ~/.openclaw/.env; set +a. FIRST check if ~/.openclaw/state/.affiliate-core-selfheal-request.json exists -- if so, this loop got stuck repeatedly and healthcheck gave up restarting it, so YOU must fix it yourself (no human, no other AI): read the file, diagnose the real root cause from logs, fix the underlying script if fixable and verify the fix, then rm that json file; if you cannot fix it after a real attempt, invoke self/issue-dev with a note, then rm the file anyway. BEFORE deciding what to do this pass (REQ-LV-020/113), read your recent metrics ledger (~/.cloak/affiliate-metrics.jsonl), your lessons ledger (state/lessons.jsonl), and this week evaluator score (evaluate_stage1(ledger_path) in ~/anicca/skills/self/self-improve/affiliate/evaluator.py, compare via beats_previous_week in .../lib/weekly_compare.py) so you make a better choice than last time -- this reading is your judgment call, nothing here is scripted. (existence-guarded: if evaluator.py/weekly_compare.py, or the loop-report.sh file used later in this pass, is absent, skip this reading step and proceed without failing the pass). THEN (1) WRITE a fresh educational slideshow deck.json to /tmp/aff-deck-$(date +%Y%m%d).json: an AI/productivity tip carousel — hook → 3-5 genuinely useful tips → soft bridge → CTA リンクはプロフィール; include a caption ending with #PR (景表法). slides[] each {n:1..N contiguous, text}. (2) PRODUCE: bash ~/profitable-claude/skills/affiliate/producer.sh /tmp/aff-deck-$(date +%Y%m%d).json (gen bg + compose + verify → ~/affiliate/queue). (3) POST: EARN_MODE=execute bash ~/profitable-claude/skills/affiliate/run.sh (drains queue → carousel to the ready affiliate account; fail-closed if no ready account). Before that, IF something did not go as intended this pass (REQ-LV-031, e.g. no ready account, post not confirmed, reCAPTCHA wall) — append ONE line {ts, pass_id, mistake, lesson} to state/lessons.jsonl describing what happened and what to do differently (your judgment, not scripted). THEN report by mail: run bash ~/anicca/skills/report/loop-report.sh affiliate \"<one-line summary of what you did this pass>\" <success, failure, or queue-empty> <usdc/commission noted this pass, or 0> \"<evidence: the actual URL of the carousel/post you published this pass, a note on the blocker if one stopped you (e.g. reCAPTCHA wall), or \"none: <reason>\" (a real reason, e.g. queue empty this pass) if nothing was posted>\" (no-ops silently if AGENTMAIL_API_KEY is not set -- only report if you were given that credential). ALSO record this pass own approximate token/compute cost for the CEO budget tracker (REQ-CEO-020): run bash ~/profitable-claude/bin/record-cost-event.sh affiliate <your own best-effort USD cost estimate for this pass -- your judgment call, a rough estimate is fine, never blocks the pass>. FINALLY touch ~/.openclaw/state/.affiliate-core-last-pass (proves this pass completed; NEVER touch on mere startup, only after the pass genuinely finishes). Report one-line JSON. NEVER post to a non-affiliate account. ¥/commission accrues later; do not fake earn. Blocker is not stop.". THEN run ONE pass now. THEN idle.'
status(){ tmux -S "$SOCK" has-session -t "$SESSION" 2>/dev/null && echo ALIVE || echo DEAD; }
case "${1:-}" in --status) status; exit 0;; --restart) tmux -S "$SOCK" kill-session -t "$SESSION" 2>/dev/null||true;; esac
[ "${1:-}" != "--restart" ] && tmux -S "$SOCK" has-session -t "$SESSION" 2>/dev/null && { echo "affiliate-core already ALIVE"; exit 0; }
# REQ-CEO-009: registry enforcement gate BEFORE spawning the tmux core (refuses to start a
# CEO-paused loop; computes/exports the effective cadence for reduce/double_down/normal).
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
source "$REPO_ROOT/lib/registry-enforce.sh"
registry_enforce_or_exit affiliate
# env -u ANTHROPIC_API_KEY: .env leaks ANTHROPIC_API_KEY into the process env, which makes the
# headless claude core hang on an interactive "use this API key?" prompt (see connector-cli.sh).
tmux -S "$SOCK" new-session -d -s "$SESSION" env -u ANTHROPIC_API_KEY "$CLAUDE" --name "$SESSION" --model sonnet --dangerously-skip-permissions --add-dir "$HOME" -- "$STARTUP"
mkdir -p "$HOME/.openclaw/state" && touch "$HOME/.openclaw/state/.affiliate-core-last-start"   # ported from gig-cli.sh: seeds the grace-window marker for healthcheck's stale-pass detection
sleep 2; echo "affiliate-core started ($(status))"
